import "core-js/modules/es.array.push.js";
import { mapGetters } from "vuex";
import backgroundManager from "@/mixins/backgroundManager";
export default {
  name: "NotFound",
  mixins: [backgroundManager],
  computed: {
    ...mapGetters("base", ["storeUseDarkMode"]),
    useDarkMode() {
      return this.storeUseDarkMode || document.documentElement.classList.contains("dark");
    },
    errorImage() {
      return this.useDarkMode ? require("@/assets/404-dark.png") : require("@/assets/404-light.png");
    }
  },
  mounted() {
    // 初始化背景图
    this.initializeBackground("uploadBkImg", ".not-found-container", true);
  },
  beforeUnmount() {
    // 清理背景轮播定时器
    this.clearBackgroundInterval();
  },
  methods: {
    goHome() {
      this.$router.push("/");
    },
    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    }
  }
};